/* @autogenerated */
import {
  AfterViewInit,
  Component,
  effect,
  ElementRef,
  input,
  OnDestroy,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatTooltipModule } from '@angular/material/tooltip';
import { DisplayProvider } from '@shared/data/display-provider';
import { SelectionModel } from '@shared/data/selection-model';

export interface MapItemMapper<T> {
  lat(item: T): number;
  lng(item: T): number;
  title(item: T): string;
  color?(item: T): string;
  icon?(item: T): string;
  popup?(item: T): string;
}

export type MapTileLayer = 'osm' | 'satellite' | 'topo';

interface MarkerEntry {
  item: any;
  marker: any; // L.Marker
}

@Component({
  selector: 'map-view',
  standalone: true,
  imports: [CommonModule, MatProgressBarModule, MatIconModule, MatButtonModule, MatTooltipModule],
  templateUrl: './map-view.component.html',
  styleUrls: ['./map-view.component.scss'],
})
export class MapViewComponent implements AfterViewInit, OnDestroy {
  data = input.required<any[] | undefined>();
  mapper = input.required<MapItemMapper<any>>();
  display = input<DisplayProvider<any>>();
  searching = input<boolean>();
  selectionModel = input<SelectionModel<any> | undefined>();
  initialLat = input<number>(40.416775);
  initialLng = input<number>(-3.70379);
  initialZoom = input<number>(6);
  tileLayer = input<MapTileLayer>('osm');
  clusterMarkers = input<boolean>(true);

  next = output<void>();
  activate = output<any>();

  readonly mapEl = viewChild.required<ElementRef<HTMLDivElement>>('mapContainer');

  readonly ready = signal(false);
  readonly mapReady = signal(false);

  private L: any = null;
  private map: any = null;
  private markersGroup: any = null;
  private markerEntries: MarkerEntry[] = [];

  private readonly TILE_URLS: Record<MapTileLayer, { url: string; attribution: string }> = {
    osm: {
      url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    },
    satellite: {
      url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
      attribution: 'Tiles © Esri',
    },
    topo: {
      url: 'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',
      attribution: '© OpenTopoMap contributors',
    },
  };

  constructor() {
    effect(() => {
      const data = this.data();
      if (this.map && this.L) {
        this.refreshMarkers(data ?? []);
      }
    });
  }

  async ngAfterViewInit(): Promise<void> {
    await this.initMap();
  }

  ngOnDestroy(): void {
    this.map?.remove();
  }

  private async initMap(): Promise<void> {
    const L = await import('leaflet');
    this.L = L;

    this.fixLeafletIconUrls(L);

    const el = this.mapEl().nativeElement;
    const tile = this.TILE_URLS[this.tileLayer()];

    this.map = L.map(el, {
      center: [this.initialLat(), this.initialLng()],
      zoom: this.initialZoom(),
      zoomControl: true,
    });

    L.tileLayer(tile.url, { attribution: tile.attribution, maxZoom: 19 }).addTo(this.map);

    this.markersGroup = L.layerGroup().addTo(this.map);

    this.mapReady.set(true);
    this.refreshMarkers(this.data() ?? []);
  }

  private refreshMarkers(items: any[]): void {
    if (!this.map || !this.L || !this.markersGroup) return;

    this.markersGroup.clearLayers();
    this.markerEntries = [];

    const m = this.mapper();
    for (const item of items) {
      const lat = m.lat(item);
      const lng = m.lng(item);
      if (!isFinite(lat) || !isFinite(lng)) continue;

      const color = m.color?.(item) ?? '#1976d2';
      const title = m.title(item);

      const icon = this.buildIcon(this.L, color);
      const marker = this.L.marker([lat, lng], { icon, title });

      const popup = m.popup?.(item) ?? `<strong>${title}</strong>`;
      marker.bindPopup(popup);
      marker.on('click', () => this.activate.emit(item));

      this.markersGroup.addLayer(marker);
      this.markerEntries.push({ item, marker });
    }

    if (this.markerEntries.length > 0) {
      const group = this.L.featureGroup(this.markerEntries.map((e) => e.marker));
      this.map.fitBounds(group.getBounds().pad(0.15));
    }
  }

  private buildIcon(L: any, color: string): any {
    const svg = `
      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="36" viewBox="0 0 24 36">
        <path d="M12 0C5.373 0 0 5.373 0 12c0 9 12 24 12 24s12-15 12-24C24 5.373 18.627 0 12 0z"
              fill="${color}" stroke="rgba(0,0,0,0.3)" stroke-width="1"/>
        <circle cx="12" cy="12" r="5" fill="rgba(255,255,255,0.8)"/>
      </svg>`;
    const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    return L.icon({ iconUrl: url, iconSize: [24, 36], iconAnchor: [12, 36], popupAnchor: [0, -36] });
  }

  private fixLeafletIconUrls(L: any): void {
    delete (L.Icon.Default.prototype as any)._getIconUrl;
    L.Icon.Default.mergeOptions({
      iconRetinaUrl: 'assets/leaflet/marker-icon-2x.png',
      iconUrl: 'assets/leaflet/marker-icon.png',
      shadowUrl: 'assets/leaflet/marker-shadow.png',
    });
  }

  fitAll(): void {
    if (!this.map || !this.L || this.markerEntries.length === 0) return;
    const group = this.L.featureGroup(this.markerEntries.map((e) => e.marker));
    this.map.fitBounds(group.getBounds().pad(0.15));
  }

  zoomIn(): void {
    this.map?.zoomIn();
  }
  zoomOut(): void {
    this.map?.zoomOut();
  }
}
